package com.procurement.invoice.entity;import com.procurement.product.entity.Product;import com.procurement.purchaseorder.entity.PurchaseOrderLine;import com.procurement.goodsreceipt.entity.GoodsReceiptLine;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name="invoice_lines")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class InvoiceLine{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="invoice_line_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="invoice_id",nullable=false)private Invoice invoice;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_line_id",nullable=false)private PurchaseOrderLine purchaseOrderLine;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="goods_receipt_line_id",nullable=false)private GoodsReceiptLine goodsReceiptLine;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@Column(nullable=false,precision=15,scale=3)private BigDecimal quantity;@Column(name="unit_price",nullable=false,precision=15,scale=2)private BigDecimal unitPrice;@Column(name="discount_percentage",nullable=false,precision=5,scale=2)@Builder.Default private BigDecimal discountPercentage=BigDecimal.ZERO;@Column(name="tax_percentage",nullable=false,precision=5,scale=2)@Builder.Default private BigDecimal taxPercentage=BigDecimal.ZERO;@Column(name="line_amount",nullable=false,precision=15,scale=2)private BigDecimal lineAmount;@Column(length=500)private String remarks;}
